    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Sirius_Arx::KEY_A_C_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Sirius_Arx::KEY_A_C_D(PARAMS_SEED);

    KeyDiffuse_B_A_C(pWorkSpace);

    //
