    // dst: [$ice]
    //
    TwistExpander_Sirius_Arx::KEY_A_C_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(SIRIUS_KEY_A_C_IceLaneA, SIRIUS_KEY_A_C_IceLaneB, SIRIUS_KEY_A_C_IceLaneC, SIRIUS_KEY_A_C_IceLaneD, &(pWorkSpace->mKeyBoxA[2U][0]));

    // Key flow — A / D

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Sirius_Arx::KEY_A_D_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Sirius_Arx::KEY_A_D_B(PARAMS_SEED);

    KeyDiffuse_A_A_D(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Sirius_Arx::KEY_A_D_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Sirius_Arx::KEY_A_D_D(PARAMS_SEED);

    KeyDiffuse_B_A_D(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Sirius_Arx::KEY_A_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(SIRIUS_KEY_A_D_IceLaneA, SIRIUS_KEY_A_D_IceLaneB, SIRIUS_KEY_A_D_IceLaneC, SIRIUS_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

    // Key flow — A / E

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Sirius_Arx::KEY_A_E_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Sirius_Arx::KEY_A_E_B(PARAMS_SEED);

    KeyDiffuse_A_A_E(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Sirius_Arx::KEY_A_E_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
